mapper.select:
SELECT id, account_number, balance
FROM accounts
WHERE user_id = #{userId}
  AND account_number = #{accountNumber}
  AND is_deleted = 0
LIMIT 1

SELECT id, account_id, card_id, external_key, transaction_date, transaction_time,
       transaction_type, transaction_region, amount, balance_after,
       merchant_name, memo, category_id
FROM transactions
WHERE account_id = #{accountId}
AND is_deleted = 0

    AND transaction_date >= #{startDate}


    AND transaction_date <= #{endDate}


    AND transaction_type = #{type}

ORDER BY transaction_date DESC, transaction_time DESC

SELECT t.id, t.account_id, t.card_id, t.external_key, t.transaction_date, t.transaction_time,
       t.transaction_type, t.transaction_region, t.amount, t.balance_after, t.merchant_name, t.memo, t.category_id
FROM transactions t
JOIN accounts a ON t.account_id = a.id
WHERE a.user_id = #{userId}
AND t.is_deleted = 0
AND a.is_deleted = 0
AND t.transaction_date >= #{startDate}
AND t.transaction_date <= #{endDate}
ORDER BY t.transaction_date DESC, t.transaction_time DESC

mapper.update:
UPDATE accounts
SET is_deleted = 1, updated_at = NOW(), deleted_at = NOW()
WHERE id = #{accountId}
AND user_id = #{userId}
AND is_deleted = 0

mapper.select:
SELECT DATE_FORMAT(t.transaction_date, '%Y-%m-%d') AS date, SUM(CASE WHEN t.transaction_type = 'DEPOSIT' THEN t.amount ELSE 0 END) AS totalDeposit, SUM(CASE WHEN t.transaction_type = 'WITHDRAWAL' THEN t.amount ELSE 0 END) AS totalWithdrawal FROM transactions t JOIN accounts a ON t.account_id = a.id WHERE a.user_id = #{userId} AND YEAR(t.transaction_date) = #{year} AND MONTH(t.transaction_date) = #{month} AND t.is_deleted = 0 AND a.is_deleted = 0
AND t.transaction_type = #{type}
GROUP BY t.transaction_date ORDER BY t.transaction_date
